#include <bits/stdc++.h>
using namespace std;

long long gcdValue(long long a, long long b) {
    while (b != 0) {
        long long remainder = a % b;
        a = b;
        b = remainder;
    }
    return a;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int tests;
    cin >> tests;
    while (tests--) {
        long long first, difference, modulus;
        cin >> first >> difference >> modulus;
        long long g = gcdValue(difference, modulus);
        cout << modulus - g + (first % g) << '\n';
    }
    return 0;
}

