#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int tests;
    cin >> tests;
    while (tests--) {
        int n;
        string s;
        cin >> n >> s;
        vector<int> unmatchedOpen;
        vector<int> unmatchedClose;
        for (int i = 0; i < n; ++i) {
            if (s[i] == '(') {
                unmatchedOpen.push_back(i + 1);
            } else if (!unmatchedOpen.empty()) {
                unmatchedOpen.pop_back();
            } else {
                unmatchedClose.push_back(i + 1);
            }
        }

        vector<int> answer;
        int closeFlips = (static_cast<int>(unmatchedClose.size()) + 1) / 2;
        for (int i = 0; i < closeFlips; ++i) answer.push_back(unmatchedClose[i]);
        int openFlips = (static_cast<int>(unmatchedOpen.size()) + 1) / 2;
        for (int i = static_cast<int>(unmatchedOpen.size()) - openFlips;
             i < static_cast<int>(unmatchedOpen.size()); ++i) {
            answer.push_back(unmatchedOpen[i]);
        }
        sort(answer.begin(), answer.end());
        cout << answer.size() << '\n';
        for (int i = 0; i < static_cast<int>(answer.size()); ++i) {
            if (i) cout << ' ';
            cout << answer[i];
        }
        cout << '\n';
    }
    return 0;
}

