#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int tests;
    cin >> tests;
    while (tests--) {
        int n, q;
        cin >> n >> q;
        vector<vector<int>> graph(n + 1);
        for (int i = 1; i < n; ++i) {
            int x, y;
            cin >> x >> y;
            graph[x].push_back(y);
            graph[y].push_back(x);
        }

        int log = 1;
        while ((1 << log) <= n) ++log;
        vector<vector<int>> up(log, vector<int>(n + 1));
        vector<int> depth(n + 1, 0);
        queue<int> bfs;
        bfs.push(1);
        up[0][1] = 1;
        vector<char> visited(n + 1, false);
        visited[1] = true;
        while (!bfs.empty()) {
            int node = bfs.front();
            bfs.pop();
            for (int next : graph[node]) {
                if (visited[next]) continue;
                visited[next] = true;
                depth[next] = depth[node] + 1;
                up[0][next] = node;
                bfs.push(next);
            }
        }
        for (int level = 1; level < log; ++level) {
            for (int node = 1; node <= n; ++node) {
                up[level][node] = up[level - 1][up[level - 1][node]];
            }
        }

        auto lca = [&](int a, int b) {
            if (depth[a] < depth[b]) swap(a, b);
            int delta = depth[a] - depth[b];
            for (int level = 0; level < log; ++level) {
                if (delta & (1 << level)) a = up[level][a];
            }
            if (a == b) return a;
            for (int level = log - 1; level >= 0; --level) {
                if (up[level][a] != up[level][b]) {
                    a = up[level][a];
                    b = up[level][b];
                }
            }
            return up[0][a];
        };

        while (q--) {
            int root, u, v;
            cin >> root >> u >> v;
            int candidates[3] = {lca(u, v), lca(u, root), lca(v, root)};
            int answer = candidates[0];
            for (int node : candidates) {
                if (depth[node] > depth[answer]) answer = node;
            }
            cout << answer << '\n';
        }
    }
    return 0;
}
